import{_ as a,o as n,a as p,b as l}from"./app.C41L12d5.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"基础API","link":"/api/SIMD-API/basic_api/basic_api"},{"text":"矩阵计算（ISASI）","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_compute_ISASI"},{"text":"矩阵搬入辅助配置接口","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/cube_load_aux_config"},{"text":"LoadImageToLocal","link":"/api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/LoadImageToLocal"}]},"headers":[],"relativePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/LoadImageToLocal.md","filePath":"api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/LoadImageToLocal.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"数据类型","slug":"数据类型","link":"#数据类型"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1788159000000}'),c={name:"api/SIMD-API/basic_api/cube_compute_ISASI/cube_load_aux_config/LoadImageToLocal.md"};function t(i,s,d,e,o,r){return n(),p("div",null,[...s[0]||(s[0]=[l(`<div><article class="markdown-body"><h1>LoadImageToLocal<span id="ZH-CN_TOPIC_0000001945534165"></span></h1><h2 id="产品支持情况">产品支持情况<span id="section1550532418810"></span><a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<span id="section618mcpsimp"></span><a class="header-anchor" href="#功能说明">​</a></h2><p>将图像数据从Global Memory搬运到Local Memory。搬运过程中可以完成图像预处理操作：包括图像翻转，改变图像尺寸（抠图，裁边，缩放，伸展），以及色域转换，类型转换等。图像预处理的相关参数通过<a href="SetAippFunctions.html">SetAippFunctions</a>进行配置。</p><h2 id="函数原型">函数原型<span id="section620mcpsimp"></span><a class="header-anchor" href="#函数原型">​</a></h2><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">template</span><span class="w"> </span><span class="o">&lt;</span><span class="k">typename</span><span class="w"> </span><span class="nc">T</span><span class="o">&gt;</span>
<span class="n">__aicore__</span><span class="w"> </span><span class="kr">inline</span><span class="w"> </span><span class="kt">void</span><span class="w"> </span><span class="n">LoadImageToLocal</span><span class="p">(</span><span class="k">const</span><span class="w"> </span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="n">T</span><span class="o">&gt;&amp;</span><span class="w"> </span><span class="n">dst</span><span class="p">,</span><span class="w"> </span><span class="k">const</span><span class="w"> </span><span class="n">LoadImageToLocalParams</span><span class="o">&amp;</span><span class="w"> </span><span class="n">loadDataParams</span><span class="p">)</span>
</code></pre></div><h2 id="参数说明">参数说明<span id="section622mcpsimp"></span><a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数，类型为LocalTensor。<br>LocalTensor的起始地址需要保证32字节对齐。</td></tr><tr><td>loadDataParams</td><td>输入</td><td>LoadData参数结构体，类型为LoadImageToLocalParams。<br>具体定义请参考：<code>\${INSTALL_DIR}/asc/include/basic_api/kernel_struct_mm.h</code>，<code>\${INSTALL_DIR}</code>请替换为CANN软件安装后文件存储路径。<br>参数说明参考<a href="#table8955841508">表2</a>。</td></tr></tbody></table><p><span id="table8955841508"></span><strong>表2</strong> LoadImageToLocalParams结构体内参数说明</p><table><thead><tr><th>参数名称</th><th>输入/输出</th><th>含义</th></tr></thead><tbody><tr><td>horizSize</td><td>输入</td><td>从源图中加载图片的水平宽度，单位为像素，取值范围：horizSize∈[2, 4095]。</td></tr><tr><td>vertSize</td><td>输入</td><td>从源图中加载图片的垂直高度，单位为像素，取值范围：vertSize∈[2, 4095]。</td></tr><tr><td>horizStartPos</td><td>输入</td><td>加载图片在源图片上的水平起始地址，单位为像素，取值范围：horizStartPos∈[0, 4095]。默认为0。<br><strong>注意：当输入图片为YUV420SP、XRGB8888、RGB888、YUV400格式时，该参数需要是偶数。</strong></td></tr><tr><td>vertStartPos</td><td>输入</td><td>加载图片在源图片上的垂直起始地址，单位为像素，取值范围：vertStartPos∈[0, 4095]。默认为0。<br><strong>注意：当输入图片为YUV420SP格式时，该参数需要是偶数。</strong></td></tr><tr><td>srcHorizSize</td><td>输入</td><td>源图像水平宽度，单位为像素，取值范围：srcHorizSize∈[2, 4095]。<br><strong>注意：当输入图片为YUV420SP格式时，该参数需要是偶数。</strong></td></tr><tr><td>topPadSize</td><td>输入</td><td>目的图像顶部填充的像素数，取值范围：topPadSize∈[0, 32]，默认为0。进行数据填充时使用，需要先调用SetAippFunctions通过AippPaddingParams配置填充的数值，再通过topPadSize、botPadSize、leftPadSize、rightPadSize配置填充的大小范围。</td></tr><tr><td>botPadSize</td><td>输入</td><td>目的图像底部填充的像素数，取值范围：botPadSize∈[0, 32]，默认为0。</td></tr><tr><td>leftPadSize</td><td>输入</td><td>目的图像左边填充的像素数，取值范围：leftPadSize∈[0, 32]，默认为0。</td></tr><tr><td>rightPadSize</td><td>输入</td><td>目的图像右边填充的像素数，取值范围：rightPadSize∈[0, 32]，默认为0。</td></tr><tr><td>sid</td><td>输入</td><td>预留参数。为后续的功能做保留，开发者暂时无需关注，使用默认值即可。</td></tr></tbody></table><h2 id="数据类型">数据类型<a class="header-anchor" href="#数据类型">​</a></h2><div data-filter="950">Ascend 950PR/Ascend 950DT，支持的数据类型为：int8_t、uint8_t、half。</div><br><div data-filter="A3">Atlas A3训练系列产品/Atlas A3推理系列产品，支持数据类型：int8_t、half。</div><br><div data-filter="910b">Atlas A2训练系列产品/Atlas A2推理系列产品，支持数据类型：int8_t、half。</div><br><div data-filter="310b">Atlas 200I/500 A2 推理产品，支持数据类型为：int8_t、uint8_t、half。</div><br><div data-filter="310p">Atlas 推理系列产品AI Core，支持的数据类型为：int8_t、uint8_t、half。</div><h2 id="返回值说明">返回值说明<span id="section640mcpsimp"></span><a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<span id="section633mcpsimp"></span><a class="header-anchor" href="#约束说明">​</a></h2><ul><li>操作数地址对齐要求请参见<a href="../../../general_description_and_constraints.html#section796754519912">通用地址对齐约束</a>。</li><li>加载到dst的图片的大小加padding的大小必须小于等于所在存储空间的大小。</li><li>当通过<a href="SetAippFunctions.html">SetAippFunctions</a>配置padding模式为块填充模式或者镜像块填充模式时，因为padding的数据来自于抠出的图片，左右padding的长度（leftPadSize、rightPadSize）必须小于或等于抠图的水平长度（horizSize），上下padding的长度（topPadSize、botPadSize）必须小于或等于抠图的垂直的长度（vertSize）。</li><li>支持的物理存储位置为：L1 Buffer（TPosition: A1/B1）。 <div data-filter="950"><ul><li>特别针对Ascend 950PR/Ascend 950DT，支持物理存储位置为：VECIN、VECCALC、VECOUT。</li></ul></div></li></ul><h2 id="调用示例">调用示例<span id="section22811728184217"></span><a class="header-anchor" href="#调用示例">​</a></h2><div data-filter="310p"><p>该调用示例支持的运行平台为Atlas 推理系列产品AI Core，示例图片格式为YUV420SP。</p><div class="code-block"><div class="code-header"><span class="lang-label">C++</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code><span class="k">constexpr</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">imageWidth</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint16_t</span><span class="w"> </span><span class="n">imageHeight</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">yPlaneSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">imageWidth</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">imageHeight</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">inputSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">yPlaneSize</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="mi">3</span><span class="w"> </span><span class="o">/</span><span class="w"> </span><span class="mi">2</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">outputChannels</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="k">constexpr</span><span class="w"> </span><span class="kt">uint32_t</span><span class="w"> </span><span class="n">dstElemCount</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">imageWidth</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">imageHeight</span><span class="w"> </span><span class="o">*</span><span class="w"> </span><span class="n">outputChannels</span><span class="p">;</span>

<span class="c1">// 源操作数：GM上一张32x32 YUV420SP图片，前1024B为Y平面，后512B为UV平面。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">GlobalTensor</span><span class="o">&lt;</span><span class="kt">uint8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">fmGlobal</span><span class="p">;</span>
<span class="n">fmGlobal</span><span class="p">.</span><span class="n">SetGlobalBuffer</span><span class="p">((</span><span class="n">__gm__</span><span class="w"> </span><span class="kt">uint8_t</span><span class="w"> </span><span class="o">*</span><span class="p">)</span><span class="n">src</span><span class="p">,</span><span class="w"> </span><span class="n">inputSize</span><span class="p">);</span>

<span class="c1">// 目的操作数：L1 Buffer。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">LocalTensor</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">featureMapA1</span><span class="p">(</span><span class="n">AscendC</span><span class="o">::</span><span class="n">TPosition</span><span class="o">::</span><span class="n">A1</span><span class="p">,</span><span class="w"> </span><span class="n">a1Addr</span><span class="p">,</span><span class="w"> </span><span class="n">dstElemCount</span><span class="p">);</span>

<span class="c1">// format = YUV420SP_U8，表示输入为uint8_t类型的YUV420 Semi-Planar图片。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">AippInputFormat</span><span class="w"> </span><span class="n">inputFormat</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="n">AscendC</span><span class="o">::</span><span class="n">AippInputFormat</span><span class="o">::</span><span class="n">YUV420SP_U8</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">AippParams</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="w"> </span><span class="n">aippConfig</span><span class="p">;</span>
<span class="c1">// 本示例不做HW padding、通道交换、单行读取、均值/缩放和色域转换，这些子参数使用结构体默认值。</span>
<span class="c1">// 输出U = int8_t时将通道padding到32通道，即每个像素输出32B。</span>
<span class="n">aippConfig</span><span class="p">.</span><span class="n">cPaddingParams</span><span class="p">.</span><span class="n">cPaddingMode</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// 通道padding补0，目的Tensor额外通道写入0。</span>
<span class="n">aippConfig</span><span class="p">.</span><span class="n">cPaddingParams</span><span class="p">.</span><span class="n">cPaddingValue</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="k">static_cast</span><span class="o">&lt;</span><span class="kt">int8_t</span><span class="o">&gt;</span><span class="p">(</span><span class="mi">0</span><span class="p">);</span>

<span class="c1">// src0为Y平面起始地址；src1为UV平面起始地址，YUV420SP 32x32的UV偏移为32 * 32 = 1024个uint8_t。</span>
<span class="n">AscendC</span><span class="o">::</span><span class="n">SetAippFunctions</span><span class="p">(</span><span class="n">fmGlobal</span><span class="p">,</span><span class="w"> </span><span class="n">fmGlobal</span><span class="p">[</span><span class="n">yPlaneSize</span><span class="p">],</span><span class="w"> </span><span class="n">inputFormat</span><span class="p">,</span><span class="w"> </span><span class="n">aippConfig</span><span class="p">);</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadImageToLocalParams</span><span class="w"> </span><span class="n">loadParams</span><span class="p">;</span>
<span class="c1">// 从源图加载32像素宽，等于整张32x32示例图的宽度。</span>
<span class="n">loadParams</span><span class="p">.</span><span class="n">horizSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="c1">// 从源图加载32像素高，等于整张32x32示例图的高度。</span>
<span class="n">loadParams</span><span class="p">.</span><span class="n">vertSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="c1">// 水平起始位置为第0个像素；YUV420SP场景要求为偶数，0满足约束。</span>
<span class="n">loadParams</span><span class="p">.</span><span class="n">horizStartPos</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// 垂直起始位置为第0行；YUV420SP场景要求为偶数，0满足约束。</span>
<span class="n">loadParams</span><span class="p">.</span><span class="n">vertStartPos</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// 源图每行宽度为32像素；YUV420SP场景要求为偶数，32满足约束。</span>
<span class="n">loadParams</span><span class="p">.</span><span class="n">srcHorizSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">32</span><span class="p">;</span>
<span class="c1">// 顶部不做HW方向padding。</span>
<span class="n">loadParams</span><span class="p">.</span><span class="n">topPadSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// 底部不做HW方向padding。</span>
<span class="n">loadParams</span><span class="p">.</span><span class="n">botPadSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// 左侧不做HW方向padding。</span>
<span class="n">loadParams</span><span class="p">.</span><span class="n">leftPadSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// 右侧不做HW方向padding。</span>
<span class="n">loadParams</span><span class="p">.</span><span class="n">rightPadSize</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>
<span class="c1">// 预留参数，固定配置为0。</span>
<span class="n">loadParams</span><span class="p">.</span><span class="n">sid</span><span class="w"> </span><span class="o">=</span><span class="w"> </span><span class="mi">0</span><span class="p">;</span>

<span class="n">AscendC</span><span class="o">::</span><span class="n">LoadImageToLocal</span><span class="p">(</span><span class="n">featureMapA1</span><span class="p">,</span><span class="w"> </span><span class="n">loadParams</span><span class="p">);</span>
</code></pre></div></div></article></div>`,1)])])}const _=a(c,[["render",t]]);export{m as __pageData,_ as default};
